CREATE TABLE "author_aliases" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "author_id" UUID NOT NULL, "alias" VARCHAR(150) NOT NULL, "normalized_alias" VARCHAR(150) NOT NULL, "confidence" DECIMAL(4,3) NOT NULL DEFAULT 0, "status" VARCHAR(20) NOT NULL DEFAULT 'PENDING', "reviewed_by_user_id" UUID, "reviewed_at" TIMESTAMPTZ(6), "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "author_aliases_pkey" PRIMARY KEY ("id"));
CREATE TABLE "publisher_aliases" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "publisher_id" UUID NOT NULL, "alias" VARCHAR(150) NOT NULL, "normalized_alias" VARCHAR(150) NOT NULL, "confidence" DECIMAL(4,3) NOT NULL DEFAULT 0, "status" VARCHAR(20) NOT NULL DEFAULT 'PENDING', "reviewed_by_user_id" UUID, "reviewed_at" TIMESTAMPTZ(6), "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "publisher_aliases_pkey" PRIMARY KEY ("id"));
CREATE TABLE "metadata_reconciliation_drafts" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "isbn" VARCHAR(20) NOT NULL, "book_id" UUID, "raw_metadata" JSONB NOT NULL DEFAULT '{}', "normalized_metadata" JSONB NOT NULL DEFAULT '{}', "ai_suggestions" JSONB NOT NULL DEFAULT '{}', "quality_warnings" JSONB NOT NULL DEFAULT '[]', "authority_matches" JSONB NOT NULL DEFAULT '{}', "explanation" JSONB NOT NULL DEFAULT '{}', "status" VARCHAR(20) NOT NULL DEFAULT 'DRAFT', "created_by_user_id" UUID NOT NULL, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "metadata_reconciliation_drafts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "metadata_reconciliation_field_decisions" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "draft_id" UUID NOT NULL, "field" VARCHAR(50) NOT NULL, "value" JSONB NOT NULL, "provenance" VARCHAR(20) NOT NULL, "status" VARCHAR(20) NOT NULL DEFAULT 'PENDING', "reviewed_by_user_id" UUID, "reviewed_at" TIMESTAMPTZ(6), CONSTRAINT "metadata_reconciliation_field_decisions_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "author_aliases_author_id_normalized_alias_key" ON "author_aliases"("author_id", "normalized_alias");
CREATE UNIQUE INDEX "publisher_aliases_publisher_id_normalized_alias_key" ON "publisher_aliases"("publisher_id", "normalized_alias");
CREATE UNIQUE INDEX "metadata_reconciliation_field_decisions_draft_id_field_key" ON "metadata_reconciliation_field_decisions"("draft_id", "field");
CREATE INDEX "metadata_reconciliation_drafts_isbn_created_at_idx" ON "metadata_reconciliation_drafts"("isbn", "created_at");
ALTER TABLE "author_aliases" ADD CONSTRAINT "author_aliases_author_id_fkey" FOREIGN KEY ("author_id") REFERENCES "authors"("id") ON DELETE CASCADE;
ALTER TABLE "publisher_aliases" ADD CONSTRAINT "publisher_aliases_publisher_id_fkey" FOREIGN KEY ("publisher_id") REFERENCES "publishers"("id") ON DELETE CASCADE;
ALTER TABLE "metadata_reconciliation_field_decisions" ADD CONSTRAINT "metadata_reconciliation_field_decisions_draft_id_fkey" FOREIGN KEY ("draft_id") REFERENCES "metadata_reconciliation_drafts"("id") ON DELETE CASCADE;
